WITH matched_keys AS (SELECT status, customer_id FROM subscriptions INTERSECT ALL SELECT status, customer_id FROM subscriptions WHERE plan IN ('enterprise', 'premium')), kept_rows AS (SELECT s.* FROM subscriptions s INNER JOIN matched_keys k ON s.status = k.status AND s.customer_id = k.customer_id) SELECT CASE WHEN monthly_fee >= 253 THEN 'PREMIUM' ELSE 'STANDARD' END AS monthly_fee_tier, SORT_ARRAY(COLLECT_SET(status)) AS status_list, COUNT(*) FILTER (WHERE plan = 'standard') AS standard_rows FROM kept_rows GROUP BY CUBE (CASE WHEN monthly_fee >= 253 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY standard_rows DESC NULLS LAST;
